// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.facadeimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.skill.BrainSkillimport com.roshan.persona.brain.skill.InputTypeimport com.roshan.persona.brain.skill.SkillCapabilityimport com.roshan.persona.brain.skill.SkillContextimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport javax.inject.Injectimport javax.inject.Singletonimport kotlin.reflect.KClass/** * NOUS — Productivity Skills (Module 14 v1.2 — Step 14.5, CRITICAL). * * Brain skill adapters that route [Intent] types to [ProductivityFacade] * operations. Each skill: *   1. Declares which intents it supports (for SkillRouter matching). *   2. Declares required Android permissions. *   3. Implements [execute] to: *      - Validate the intent slots (return NeedsInput if missing). *      - Call the corresponding [ProductivityFacade] method. *      - Convert the [ProductivityResult] to a [SkillOutput] via the *        `toSkillOutput()` extension (per strategy v1.1 §"Shift 3"). * * ## Brain Skill Contract * * All skills return `Result<SkillOutput>` (not raw SkillOutput). The * `Result.Success` wrapper carries correlationId + durationNanos metadata * for tracing. We use `Result.Success(data = ..., correlationId = ..., durationNanos = 0)` * — the actual operation timing is recorded inside the engines. * * ## Intent → Facade Mapping * * | Intent | Skill | Facade Method | * |--------|-------|---------------| * | Intent.SetAlarm | AlarmSkill | facade.setAlarm | * | Intent.SetTimer | TimerSkill | facade.setTimer | * | Intent.SetReminder | ReminderSkill | facade.setReminder | * | Intent.CreateNote | NoteSkill | facade.createNote | * | Intent.CreateCalendarEvent | CalendarSkill | facade.createCalendarEvent | * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Shift 3</a> */// ═══════════════════════════════════════════════════════════════════════════// Alarm Skill// ═══════════════════════════════════════════════════════════════════════════/** * Handles `Intent.SetAlarm` — sets an alarm at a specific time. * * User-facing examples: *   - "7 baje alarm lagao" → SetAlarm(time="7:00", label=null) *   - "Set alarm for 6 AM tomorrow" → SetAlarm(time="6 AM", label=null) */@Singletonclass AlarmSkill @Inject constructor(    private val facade: ProductivityFacade,) : BrainSkill {    override val id = "set_alarm"    override val displayName = "Set Alarm"    override val description = "Set an alarm at a specific time"    override val capabilities = setOf(        SkillCapability("set_alarms", "Set alarms at specific times"),    )    override val requiredPermissions = setOf(        "android.permission.SCHEDULE_EXACT_ALARM",        "android.permission.POST_NOTIFICATIONS",    )    override val supportedIntents: Set<KClass<out Intent>> = setOf(Intent.SetAlarm::class)    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val alarmIntent = intent as? Intent.SetAlarm            ?: return failure(context, id, "Not a SetAlarm intent")        // Capture into local val so Kotlin can smart-cast to String        // (public API properties declared in a different module cannot be smart-cast directly).        val time = alarmIntent.time        if (time.isNullOrBlank()) {            return success(                context,                SkillOutput.NeedsInput(                    skillId = id,                    prompt = "What time should I set the alarm for?",                    inputType = InputType.TIME,                ),            )        }        // Call facade — converts to ProductivityResult.        val result = facade.setAlarm(time, alarmIntent.label)        return success(context, result.toSkillOutput(id))    }}// ═══════════════════════════════════════════════════════════════════════════// Timer Skill// ═══════════════════════════════════════════════════════════════════════════/** * Handles `Intent.SetTimer` — sets a timer for a duration. * * User-facing examples: *   - "10 minute ka timer lagao" → SetTimer(duration="10 minutes", label=null) *   - "Set a 5 minute timer for pasta" → SetTimer(duration="5 minutes", label="pasta") */@Singletonclass TimerSkill @Inject constructor(    private val facade: ProductivityFacade,) : BrainSkill {    override val id = "set_timer"    override val displayName = "Set Timer"    override val description = "Set a timer for a duration"    override val capabilities = setOf(        SkillCapability("set_timers", "Set countdown timers"),    )    override val requiredPermissions = setOf(        "android.permission.SCHEDULE_EXACT_ALARM",        "android.permission.POST_NOTIFICATIONS",    )    override val supportedIntents: Set<KClass<out Intent>> = setOf(Intent.SetTimer::class)    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val timerIntent = intent as? Intent.SetTimer            ?: return failure(context, id, "Not a SetTimer intent")        val duration = timerIntent.duration        if (duration.isNullOrBlank()) {            return success(                context,                SkillOutput.NeedsInput(                    skillId = id,                    prompt = "How long should the timer be?",                    inputType = InputType.DURATION,                ),            )        }        val result = facade.setTimer(duration, timerIntent.label)        return success(context, result.toSkillOutput(id))    }}// ═══════════════════════════════════════════════════════════════════════════// Reminder Skill// ═══════════════════════════════════════════════════════════════════════════/** * Handles `Intent.SetReminder` — schedules a reminder (encrypted body + WorkManager). * * User-facing examples: *   - "Kal 3 baje 'medicine le' reminder set karo" *       → SetReminder(text="medicine le", time="tomorrow 3 PM") *   - "In 2 hours, remind me to call mom" *       → SetReminder(text="call mom", time="in 2 hours") */@Singletonclass ReminderSkill @Inject constructor(    private val facade: ProductivityFacade,) : BrainSkill {    override val id = "set_reminder"    override val displayName = "Set Reminder"    override val description = "Set a reminder with text + time"    override val capabilities = setOf(        SkillCapability("set_reminders", "Schedule text reminders"),    )    override val requiredPermissions = setOf(        "android.permission.POST_NOTIFICATIONS",    )    override val supportedIntents: Set<KClass<out Intent>> = setOf(Intent.SetReminder::class)    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val reminderIntent = intent as? Intent.SetReminder            ?: return failure(context, id, "Not a SetReminder intent")        val text = reminderIntent.text        if (text.isNullOrBlank()) {            return success(                context,                SkillOutput.NeedsInput(                    skillId = id,                    prompt = "What should I remind you about?",                    inputType = InputType.TEXT,                ),            )        }        val time = reminderIntent.time        if (time.isNullOrBlank()) {            return success(                context,                SkillOutput.NeedsInput(                    skillId = id,                    prompt = "When should I remind you?",                    inputType = InputType.TIME,                ),            )        }        val result = facade.setReminder(text, time)        return success(context, result.toSkillOutput(id))    }}// ═══════════════════════════════════════════════════════════════════════════// Note Skill// ═══════════════════════════════════════════════════════════════════════════/** * Handles `Intent.CreateNote` — creates an encrypted note. * * User-facing examples: *   - "Note banao 'buy milk'" → CreateNote(text="buy milk") *   - "Remember that the WiFi password is openwrt-1234" → CreateNote(text="WiFi password is openwrt-1234") */@Singletonclass NoteSkill @Inject constructor(    private val facade: ProductivityFacade,) : BrainSkill {    override val id = "create_note"    override val displayName = "Create Note"    override val description = "Create a new note (encrypted)"    override val capabilities = setOf(        SkillCapability("create_notes", "Create encrypted notes"),    )    override val requiredPermissions = emptySet<String>()  // Notes don't need runtime permissions.    override val supportedIntents: Set<KClass<out Intent>> = setOf(Intent.CreateNote::class)    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val noteIntent = intent as? Intent.CreateNote            ?: return failure(context, id, "Not a CreateNote intent")        val text = noteIntent.text        if (text.isNullOrBlank()) {            return success(                context,                SkillOutput.NeedsInput(                    skillId = id,                    prompt = "What should I write in the note?",                    inputType = InputType.TEXT,                ),            )        }        val result = facade.createNote(text)        return success(context, result.toSkillOutput(id))    }}// ═══════════════════════════════════════════════════════════════════════════// Calendar Skill// ═══════════════════════════════════════════════════════════════════════════/** * Handles `Intent.CreateCalendarEvent` — creates a calendar event with reminder. * * User-facing examples: *   - "Kal 3 baje meeting set karo" → CreateCalendarEvent(title="Meeting", time="tomorrow 3 PM", location=null) *   - "Doctor appointment tomorrow at 10 AM at Apollo Hospital" *       → CreateCalendarEvent(title="Doctor appointment", time="tomorrow 10 AM", location="Apollo Hospital") * * Uses `createCalendarEventWithReminder` (per strategy v1.2 §"Polish 4") — * sets a 15-minute reminder by default. */@Singletonclass CalendarSkill @Inject constructor(    private val facade: ProductivityFacade,) : BrainSkill {    override val id = "create_calendar_event"    override val displayName = "Create Calendar Event"    override val description = "Create a calendar event with reminder"    override val capabilities = setOf(        SkillCapability("create_calendar_events", "Create calendar events"),    )    override val requiredPermissions = setOf(        "android.permission.WRITE_CALENDAR",        "android.permission.READ_CALENDAR",    )    override val supportedIntents: Set<KClass<out Intent>> = setOf(Intent.CreateCalendarEvent::class)    override suspend fun execute(intent: Intent, context: SkillContext): Result<SkillOutput> {        val calIntent = intent as? Intent.CreateCalendarEvent            ?: return failure(context, id, "Not a CreateCalendarEvent intent")        val title = calIntent.title        if (title.isNullOrBlank()) {            return success(                context,                SkillOutput.NeedsInput(                    skillId = id,                    prompt = "What's the event title?",                    inputType = InputType.TEXT,                ),            )        }        val time = calIntent.time        if (time.isNullOrBlank()) {            return success(                context,                SkillOutput.NeedsInput(                    skillId = id,                    prompt = "When is the event?",                    inputType = InputType.TIME,                ),            )        }        // Use createCalendarEventWithReminder (per strategy v1.2 §"Polish 4").        val result = facade.createCalendarEventWithReminder(            title = title,            timeStr = time,            location = calIntent.location,        )        return success(context, result.toSkillOutput(id))    }}// ═══════════════════════════════════════════════════════════════════════════// Internal helpers — build Result.Success wrappers// ═══════════════════════════════════════════════════════════════════════════/** Build a `Result.Success<SkillOutput>` from a SkillOutput, attaching the correlation ID. */private fun success(    context: SkillContext,    output: SkillOutput,): Result<SkillOutput> = Result.Success(    data = output,    correlationId = context.brainContext.correlationId,    durationNanos = 0,)/** Build a `Result.Success<SkillOutput.Failure>` for an unsupported intent. */private fun failure(    context: SkillContext,    skillId: String,    reason: String,): Result<SkillOutput> = Result.Success(    data = SkillOutput.Failure(        error = com.roshan.persona.common.AppError.Skill.Crashed(            skillName = skillId,            cause = IllegalArgumentException(reason),        ),    ),    correlationId = context.brainContext.correlationId,    durationNanos = 0,)